import sys, yaml, json
data = yaml.safe_load(sys.stdin.read())
exps = data if isinstance(data, dict) and 'experiments' not in data else data.get('experiments', data.get('data', {}).get('experiments', data))
if isinstance(exps, dict) and 'data' in exps and isinstance(exps['data'], dict) and 'experiments' in exps['data']:
    exps = exps['data']['experiments']
elif isinstance(exps, dict) and 'experiments' in exps:
    exps = exps['experiments']

# Get ISR b03 experiments and H8 experiments
targets = {}
for exp_id, exp in exps.items():
    if not isinstance(exp, dict):
        continue
    # beta=0.3 ISR experiments
    if 'b03' in exp_id and 'isr' in exp_id.lower():
        targets[exp_id] = exp
    # Also get random b03 experiments
    if 'b03' in exp_id and 'random' in exp_id.lower():
        targets[exp_id] = exp
    # H8 related - exec only with 1000 steps
    if 'exec' in exp_id.lower() and ('1000' in exp_id or '1k' in exp_id.lower()):
        targets[exp_id] = exp
    # Any experiment mentioning H8=15
    if isinstance(exp.get('metrics'), dict) and exp['metrics'].get('h8_count') is not None:
        m = exp['metrics']
        if m.get('h8_count', 0) >= 10:
            targets[exp_id] = exp

for exp_id in sorted(targets.keys()):
    exp = targets[exp_id]
    print(f'=== {exp_id} ===')
    print(f'  status: {exp.get(\"status\")}')
    m = exp.get('metrics', {})
    if m:
        print(f'  metrics: {json.dumps(m, indent=4, default=str)}')
    c = exp.get('conclusion')
    if c:
        print(f'  conclusion: {c}')
    print()
